// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Bound;
import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Filter.ConditionBindingScope;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class PackedTermBindingMasksTest {
	private static final IRI P = SimpleValueFactory.getInstance().createIRI("urn:mask:predicate");

	@Test
	void trueConstantIsNotAnOutputWhenAFilterInternsItsName() {
		StatementPattern pattern = pattern(Var.of("fixed", P, true, true));
		PackedQuery bare = PackedQueryCodec.encode(pattern.clone());
		assertThat(outputNames(bare)).containsExactlyInAnyOrder("s", "o");

		Filter filter = new Filter(pattern.clone(), new Bound(Var.of("o")));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("s", "o", "fixed")));
		PackedQuery wrapped = PackedQueryCodec.encode(filter);
		assertThat(outputNames(wrapped)).containsExactlyInAnyOrder("s", "o");
		assertThat(wrapped.bindingNames(wrapped.relOutputMaskId(wrapped.relChild(wrapped.rootRelId(), 0))))
				.containsExactlyInAnyOrder("s", "o");
	}

	@Test
	void valuedNonconstantTupleNameIsAnOutputEvenWithoutAFilterInterningIt() {
		StatementPattern pattern = pattern(Var.of("inputPredicate", P, false, false));
		PackedQuery bare = PackedQueryCodec.encode(pattern.clone());
		assertThat(outputNames(bare)).containsExactlyInAnyOrder("s", "o", "inputPredicate");

		Filter filter = new Filter(pattern.clone(), new Bound(Var.of("o")));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("s", "o", "inputPredicate")));
		PackedQuery wrapped = PackedQueryCodec.encode(filter);
		assertThat(outputNames(wrapped)).containsExactlyInAnyOrder("s", "o", "inputPredicate");
	}

	@Test
	void valuedScalarUsesItsValueEvenWhenItsNameIsInterned() {
		Filter filter = new Filter(new SingletonSet(), new Bound(Var.of("folded", P, false, false)));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("folded")));
		PackedQuery query = PackedQueryCodec.encode(filter);
		int condition = query.filterCondition(query.rootRelId());
		assertThat(query.bindingNames(query.scalarDependencyMaskId(condition))).isEmpty();
	}

	@Test
	void unvaluedConstantFlagScalarStillReadsItsNamedInput() {
		Filter filter = new Filter(new SingletonSet(), new Bound(Var.of("unbound", null, false, true)));
		PackedQuery query = PackedQueryCodec.encode(filter);
		int condition = query.filterCondition(query.rootRelId());
		assertThat(query.bindingNames(query.scalarDependencyMaskId(condition))).containsExactly("unbound");
	}

	@Test
	void embeddedTupleReferencesIncludeFoldedParametersButExcludeTrueConstants() {
		StatementPattern body = new StatementPattern(Var.of("foldedSubject", P, false, false),
				Var.of("fixed", P, true, true), Var.of("o"));
		Filter root = new Filter(new SingletonSet(), new Exists(body));
		PackedQuery query = PackedQueryCodec.encode(root);
		int exists = query.filterCondition(query.rootRelId());
		assertThat(query.bindingNames(query.scalarEmbeddedReferenceMaskId(exists)))
				.containsExactlyInAnyOrder("foldedSubject", "o");
	}

	private static StatementPattern pattern(Var predicate) {
		return new StatementPattern(Var.of("s"), predicate, Var.of("o"));
	}

	private static Set<String> outputNames(PackedQuery query) {
		return Set.copyOf(query.bindingNames(query.relOutputMaskId(query.rootRelId())));
	}
}
